/**
 * cardNames.js — the word a card contributes to its host item's displayed name.
 *
 * In the game this is a CLIENT concern: the server stores "Gladius, cards 4092, 4092,
 * 4035" and the client renders "+7 Double Boned Bloody Gladius". We render the same
 * string for the same reason the client does — a build is easier to recognise by the
 * name a player would read off their own inventory than by a list of card names.
 *
 * The data is generated by tools/gen-card-names.mjs from the client's own two tables;
 * see that file for provenance. Nothing here is PS-specific: card ids are vanilla and
 * these are display names, which no server-side rework changes. A card with no entry —
 * every PS custom, and a few vanilla ones — contributes no word, exactly as in-game.
 */
const CARD_NAMES = require("./data/card_names.json").cards;

/**
 * The name fragment for a card id, or null.
 * @returns {{name: string, after: boolean}|null}
 */
function cardNameFragment(id) {
  const e = CARD_NAMES[String(id)];
  return e ? { name: e.n, after: !!e.after } : null;
}

module.exports = { cardNameFragment, CARD_NAMES };
